function escapeHtml(text) {
  if (!text) return '';
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

const inputData = $input.first().json;
const records = inputData?.output?.output || inputData?.output || [];
const safeRecords = Array.isArray(records) ? records : [records];

let message = "<b>📊 POST MONITORING SUMMARY</b>\n\n";

safeRecords.forEach((item, index) => {
  const title = escapeHtml(item.title).toUpperCase();
  const content = escapeHtml(item.content);
  const comment = escapeHtml(item.comment);
  const link = item.link;

  const isSafe = item.review && item.review.toLowerCase() === 'safe';
  const reviewLabel = isSafe ? "✅ Safe" : "⚠️ Flagged / Toxic";

  message += `<b>${index + 1}. ${title}</b>\n`;
  message += `📝 <i>${content}</i>\n`;
  message += `💬 ${comment}\n`;
  message += `🛡️ Evaluation: <b>${reviewLabel}</b>\n`;
  message += `🔗 <a href="${link}">View Post</a>\n`;
  message += `──────────────────\n\n`;
});

return {
  json: {
    telegram_message: message.trim()
  }
};
